489	void d256_store_initial_factor_panel_and_half(
490	        const float* factor,
491	        const float* panel,
492	        float* output,
493	        __half* sidecar) {
494	    constexpr int factor_ld = 68;
495	    constexpr int panel_ld = 32;
496	    constexpr int output_ld = 256;
497	    constexpr int sidecar_ld = 64;
498	    constexpr long long matrix_elements = 256LL * 256LL;
499	    constexpr long long sidecar_tile_elements = 64LL * 64LL;
500	    const int panel_group = blockIdx.z;
501	    const int sample = blockIdx.y;
502	    const int task = (panel_group << 1) + blockIdx.x;
503	    const int panel_tile = 1 + (task >> 1);
504	    const int panel_half = task & 1;
505	    const long long sample_base = sample * matrix_elements;
506	    const long long panel_output_index =
507	        sample_base + panel_tile * 64 + panel_half * 32;
508	    const long long sidecar_index =
509	        (sample * 5LL + panel_tile - 1) * sidecar_tile_elements
510	        + panel_half * 32;
511	
512	    const int row = threadIdx.x >> 3;
513	    const int col = (threadIdx.x & 7) * 4;
514	    #pragma unroll
515	    for (int load = 0; load < 4; ++load) {
516	        const int current_row = row + load * 16;
517	        const float4 panel_values = *reinterpret_cast<const float4*>(
518	            panel + current_row * panel_ld + col);
519	        *reinterpret_cast<float4*>(
520	            output + panel_output_index + current_row * output_ld + col) =
521	            panel_values;
